import sys

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return

    first_line = data[0].split()
    if not first_line:
        return

    N = int(first_line[0])
    B = int(first_line[1]) if len(first_line) > 1 else 0

    boxes = []
    for i in range(1, 1 + B):
        if i < len(data):
            line = data[i].split()
            if line:
                boxes.append(line)

    result = []
    for box in boxes:
        has_spoilt = False
        for apple in box:
            if apple.lower() == 'x':
                has_spoilt = True
                break

        if has_spoilt:
            new_box = ['X'] * len(box)
        else:
            new_box = ['A'] * len(box)
        result.append(new_box)

    for line in result:
        print(' '.join(line))

if __name__ == "__main__":
    main()
